package com.mak.feastit.remote

import okhttp3.Interceptor
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.Protocol
import okhttp3.Response
import okhttp3.ResponseBody.Companion.toResponseBody

/**
 * This will help us to test our networking code while a particular API is not implemented
 * yet on Backend side.
 */
class MockInterceptor : Interceptor {

    override fun intercept(chain: Interceptor.Chain): Response {
//        if (BuildConfig.DEBUG) {
            val uri = chain.request().url.toUri().toString()
            val responseString = when {
                uri.contains(API_COMPLEX_SEARCH_RECIPES) -> COMPLEX_SEARCH_RESPONSE
                uri.contains("/analyzedInstructions") -> ANALYSED_RECIPE_RESPONSE
                else -> ""
            }

            return chain.proceed(chain.request())
                .newBuilder()
                .code(API_RESPONSE_CODE)
                .protocol(Protocol.HTTP_2)
                .message(responseString)
                .body(
                    responseString.toByteArray()
                        .toResponseBody("application/json".toMediaTypeOrNull())
                )
                .addHeader("content-type", "application/json")
                .build()
//        } else {
            //just to be on safe side.
            throw IllegalAccessError("MockInterceptor is only meant for Testing Purposes and " +
                    "bound to be used only with DEBUG mode")
//        }
    }

}

private const val API_RESPONSE_CODE = 200
internal const val API_COMPLEX_SEARCH_RECIPES = "/recipes/complexSearch"
internal const val API_PATH_ID = "recipeId"
internal const val API_GET_RECIPE_DETAIL = "/recipes/{${API_PATH_ID}}/information"
internal const val API_GET_RECIPE_ANALYSED_INSTRUCTION = "/recipes/{${API_PATH_ID}}/analyzedInstructions"
